#include "UbuntuFonts.h"
#include "fonts.h"

unsigned char Ubuntu24_raw[];




void LCD_DrawChar16x24(uint16_t x,
                       uint16_t y,
                       const uint8_t *glyph,
                       uint16_t color)
{
    for(int row=0; row<24; row++)
    {
        uint16_t line = (glyph[row*2] << 8) | glyph[row*2+1];

        for(int col=0; col<16; col++)
        {
            if(line & (1 << (15-col)))
            {
                DD_LCD_DrawPixel(x+col, y+row, color);
            }
        }
    }
}

void LCD_DrawRectangle(uint16_t x,uint16_t y,uint16_t w,uint16_t h,uint16_t color)
{
    uint16_t *fb = (uint16_t*)LCD_FRAMEBUFFER;

    for(int j=0;j<h;j++)
    {
        for(int i=0;i<w;i++)
        {
            fb[(y+j)*800 + (x+i)] = color;
        }
    }
}


extern const uint8_t Font24_Table [];

void DD_LCD_DrawChar24(uint16_t x, uint16_t y, char c, uint16_t color)
{
    uint32_t index = (c - 32) * 48;   // 16x24 font = 48 bytes per char

    for(int row = 0; row < 24; row++)
    {
        for(int col = 0; col < 16; col++)
        {
            uint8_t byte = Font24_Table[index + (row * 2) + (col / 8)];
            uint8_t bit  = 7 - (col % 8);

            if(byte & (1 << bit))
            {
                DD_LCD_DrawPixel(x + col, y + row, color);
            }
        }
    }
}

